// Embeds the SQL files as a TypeScript module so Workers, which have no filesystem,
// carry the same migrations Node does. `--check` fails if the module is stale.
import { readFileSync, readdirSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', 'apps', 'api');
const lines = [
  '// Generated by scripts/embed-migrations.mjs from apps/api/migrations. Do not edit.',
  "import type { Migration } from './migrate.ts';",
  '',
];
for (const line of ['workspace', 'control']) {
  const dir = join(root, 'migrations', line);
  const files = existsSync(dir)
    ? readdirSync(dir)
        .filter((f) => /^\d{4}_.+\.sql$/.test(f))
        .sort()
    : [];
  const items = files.map((f) => {
    const [, num, name] = /^(\d{4})_(.+)\.sql$/.exec(f);
    return `  { version: ${Number(num)}, name: ${JSON.stringify(name)}, sql: ${JSON.stringify(readFileSync(join(dir, f), 'utf8'))} },`;
  });
  lines.push(`export const ${line.toUpperCase()}_MIGRATIONS: Migration[] = [`, ...items, '];', '');
}
const out = lines.join('\n');
const target = join(root, 'src', 'db', 'migrations.generated.ts');
if (process.argv.includes('--check')) {
  const have = existsSync(target) ? readFileSync(target, 'utf8') : '';
  if (have !== out) {
    console.error('migrations.generated.ts is out of date: run node scripts/embed-migrations.mjs');
    process.exit(1);
  }
} else {
  writeFileSync(target, out);
  console.log('wrote', target);
}
